-- Article demandé par Tom le 26/10/2026 : classement vérifié sur Foot Mercato, ESPN et USA Today.
INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured")
SELECT 'Ballon d''Or 2026 : le classement complet, de Harry Kane à la 29e place', 'ballon-d-or-2026-le-classement-complet', 'Harry Kane devant Kylian Mbappé et Lamine Yamal : voici les 30 joueurs classés du Ballon d''Or 2026, avec une égalité à la 29e place.', '<p>Le London Palladium a livré son verdict lundi soir : ⭐ Harry Kane est le Ballon d''Or 2026. Derrière l''attaquant anglais, Kylian Mbappé et Lamine Yamal complètent le podium. Voici le classement complet des joueurs retenus par le jury, de la 1re à la 29e place, avec une égalité qui explique l''absence de 30e.</p><p>Le récit de la soirée et le palmarès des autres trophées sont à lire ici : <a href="/articles/ballon-d-or-2026-harry-kane-sacre-meilleur-joueur-du-monde">Harry Kane sacré meilleur joueur du monde</a>.</p><h2>Le podium</h2><ol start="1"><li>⭐ Harry Kane (Bayern Munich, Angleterre)</li><li>Kylian Mbappé (Real Madrid, France)</li><li>Lamine Yamal (FC Barcelone, Espagne)</li></ol><h2>De la 4e à la 10e place</h2><ol start="4"><li>Rodri (FC Barcelone, Espagne)</li><li>Lionel Messi (Inter Miami, Argentine)</li><li>Khvicha Kvaratskhelia (PSG, Géorgie)</li><li>Ousmane Dembélé (PSG, France)</li><li>Erling Haaland (Manchester City, Norvège)</li><li>Michael Olise (Bayern Munich, France)</li><li>Fabián Ruiz (PSG, Espagne)</li></ol><h2>De la 11e à la 20e place</h2><ol start="11"><li>Jude Bellingham (Real Madrid, Angleterre)</li><li>Pau Cubarsí (FC Barcelone, Espagne)</li><li>Achraf Hakimi (PSG, Maroc)</li><li>Vitinha (PSG, Portugal)</li><li>Declan Rice (Arsenal, Angleterre)</li><li>Ferran Torres (PSG, Espagne)</li><li>Vinícius Júnior (Real Madrid, Brésil)</li><li>Marc Cucurella (Real Madrid, Espagne)</li><li>João Neves (PSG, Portugal)</li><li>Willian Pacho (PSG, Équateur)</li></ol><h2>De la 21e à la 29e place</h2><ol start="21"><li>Gabriel (Arsenal, Brésil)</li><li>Lautaro Martínez (Inter Milan, Argentine)</li><li>Nuno Mendes (PSG, Portugal)</li><li>Luis Díaz (Bayern Munich, Colombie)</li><li>Marquinhos (PSG, Brésil)</li><li>Dayot Upamecano (Bayern Munich, France)</li><li>Bruno Fernandes (Manchester United, Portugal)</li><li>Julián Quiñones (Al-Qadsiah, Mexique)</li></ol><ul><li>29e ex aequo : William Saliba (Arsenal, France) et Sadio Mané (Al-Nassr, Sénégal)</li></ul><p>Ferran Torres et Marc Cucurella ont changé de club depuis la période de vote : ils figurent ici sous leur club actuel.</p><h2>Ce qu''il faut retenir</h2><ul><li>Le PSG place dix joueurs dans le classement, de Kvaratskhelia (6e) à Marquinhos (25e). Aucun club n''en compte autant.</li><li>Ousmane Dembélé, tenant du titre, termine 7e.</li><li>Lionel Messi est toujours là : 5e avec l''Inter Miami.</li><li>Notre pronostic surprise, Fabián Ruiz, entre dans le top 10. Khvicha Kvaratskhelia, privé de Coupe du monde avec la Géorgie, prend la 6e place. Relisez <a href="/articles/ballon-d-or-2026-le-trone-sans-roi">notre avant-cérémonie</a>.</li><li>Pau Cubarsí, à qui Lamine Yamal a dédié son trophée Kopa, se classe 12e.</li></ul><h2>Sources</h2><p>Classement publié à l''issue de la cérémonie et vérifié sur trois médias : <a href="https://www.footmercato.net/a7319110063199534207-le-classement-final-du-ballon-dor-2026" target="_blank" rel="noopener noreferrer">Foot Mercato</a>, <a href="https://www.espn.com/soccer/story/_/id/50289067/ballon-dor-2026-results-full-rankings-all-award-winners" target="_blank" rel="noopener noreferrer">ESPN</a> et <a href="https://sports.yahoo.com/articles/2026-ballon-dor-final-rankings-230119799.html" target="_blank" rel="noopener noreferrer">USA Today / Yahoo Sports</a>. ⚽</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'actualites'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 3, false
ON CONFLICT ("slug") DO NOTHING;
